/* Student's Book va Workbook audiolari: audio/a2/student, audio/a2/workbook.
   Matnlar audiodan avtomatik chiqarilgan. Dars: { id, u, book, title, dur (soniya), audio, lines: [[kim, inglizcha, oʻzbekcha, soniya], ...] }
   Savollar (q) va oʻzbekcha tarjima hali yoʻq — ularni qoʻshsangiz, sahifa oʻzi koʻrsatadi. */
var AUDIO_LESSONS = [{"id":"sb-01","u":1,"book":"Student's Book","title":"Daily Routines and Habits","dur":131,"audio":"audio/a2/student/unit-01.mp3","lines":[["","Good morning. I'm doing a survey about people's daily routines.","",5.4],["","Could I ask you a few questions? Sure.","",9.7],["","Great. First, can I have your name? Yes, it's Sophie Carter.","",13.3],["","Could you spell your surname, please? Sure. It's C-A-R-T-E-R.","",19.7],["","Thank you. Now, let's talk about your mornings. What time do you usually get up?","",27.9],["","Quite early. My alarm goes off at 6, but I don't get up immediately. I usually stay in bed for","",34.0],["","another 15 minutes, so I get up at 6.15. Then I have a shower and get dressed.","",40.9],["","Do you have breakfast at home? Yes, always. I usually have some cereal and a banana.","",48.0],["","I used to drink coffee in the morning, but these days I prefer tea.","",55.4],["","And what time do you leave home? At about 7.20. I work at a","",60.2],["","bookshop in the town centre, and I normally go there by bus.","",65.2],["","Is it a long journey? Not really. It usually takes about 30 minutes.","",69.7],["","I sometimes listen to music on the bus, but I often just look out of the window.","",75.8],["","What happens after work? I finish at half past four.","",81.1],["","On Tuesdays, I go swimming at the sports centre. I swim for about an hour,","",85.6],["","so I normally get home just after six. What do you do in the evening?","",90.8],["","I make dinner first. I really enjoy cooking, especially pasta and soup.","",96.1],["","After dinner, I usually watch TV or talk to my friends online.","",102.1],["","And what time do you normally go to bed? Around 10.45. Before I sleep,","",107.0],["","I usually read for about 20 minutes. It helps me relax.","",113.5],["","One last question. Are weekends different?","",118.5],["","Very different. On Saturdays, I don't use an alarm.","",122.2],["","I usually wake up around nine and meet my friends for breakfast.","",126.5]]},
{"id":"sb-02","u":2,"book":"Student's Book","title":"Family, Friends and Relationships","dur":131,"audio":"audio/a2/student/unit-02.mp3","lines":[["","Hi, I'm collecting information for a class project about families and friendships.","",6.0],["","Can I ask you a few questions?","",11.4],["","Sure, that sounds interesting.","",13.8],["","Great! First, could you tell me your name?","",16.6],["","My name's Lucy Bennett.","",20.6],["","Could you spell your surname, please?","",23.3],["","Yes, it's B-E-N-N-E-T-T.","",25.1],["","Thanks. So, Lucy, do you have a big family?","",32.6],["","Not really. There are four people in my family. My parents, my younger brother and me. My brother's","",37.5],["","name is Jack. He's 15, so he's three years younger than I am.","",44.9],["","Do you spend much time together?","",50.2],["","Yes, especially at weekends. Jack and I sometimes argue about small things,","",52.6],["","but we're actually quite close. We both love films, so we usually watch one together on Friday evenings.","",58.6],["","What about your parents?","",66.2],["","My mum works at a hospital, and my dad is a bus driver. They're both busy during the week.","",68.6],["","We always try to have dinner together at about 7.30.","",75.1],["","Do any other relatives live near you?","",79.1],["","My grandmother does. She lives about 10 minutes away, so I visit her every Wednesday after college.","",82.1],["","We usually have tea and talk for an hour or two.","",88.7],["","And what about your friends? Who are you closest to?","",92.4],["","My best friend is Emma. We met at primary school when we were seven. She's friendly and really","",96.5],["","funny. We don't study at the same college now, but we still see each other regularly.","",103.0],["","When do you normally meet?","",108.8],["","Usually on Saturdays. We often go shopping or meet at a café called Corner.","",110.1],["","Sometimes we just walk around town and talk.","",117.3],["","How often do you speak during the week?","",120.6],["","Almost every day. We usually send messages, and we have a longer phone call on Thursday evenings.","",123.8]]},
{"id":"sb-03","u":3,"book":"Student's Book","title":"Hobbies and free time","dur":123,"audio":"audio/a2/student/unit-03.mp3","lines":[["","Hi. I'm doing a survey about how people spend their free time. Could I ask you a few questions?","",4.5],["","Of course.","",11.6],["","Great. First, what's your name?","",13.2],["","My name's Anna Wilson.","",16.4],["","Could you spell your surname for me?","",19.1],["","Sure. It's W-I-L-S-O-N.","",21.8],["","Thanks. So, Anna, what do you like doing in your free time?","",27.4],["","I have several hobbies, but my favourite is photography.","",32.8],["","I started about two years ago when my parents gave me a camera for my birthday.","",37.1],["","I usually take pictures of buildings, streets and people.","",42.3],["","When do you normally have time for photography?","",46.6],["","Mostly at the weekend. On Saturday mornings, I usually walk around the town centre with","",49.9],["","my camera. I sometimes spend two or three hours outside if the weather is nice.","",55.4],["","Do you prefer doing things outside?","",61.3],["","Not always. During the week, I often stay at home after work. I enjoy reading,","",64.5],["","especially adventure stories. I normally read for about 30 minutes before dinner.","",70.9],["","Do you have any hobbies that you do with other people?","",76.9],["","Yes. My friend Chloe and I go to a dance class together. We used to go on Tuesdays,","",80.3],["","but the class moved to Thursday this month. It starts at seven in the evening.","",86.6],["","That sounds busy. Do you have time to relax?","",91.8],["","Definitely. I don't like planning every minute of my free time.","",96.1],["","Some evenings, I just listen to music or watch something online.","",100.8],["","Is there anything new you'd like to try?","",105.3],["","Yes, actually. I'd really like to learn painting.","",108.3],["","There's an art club near my house, and I'm thinking about joining it next month.","",112.3],["","Sounds good. Thanks for answering my questions.","",117.8],["","You're welcome.","",121.3]]},
{"id":"sb-04","u":4,"book":"Student's Book","title":"Food, Cooking and Eating","dur":124,"audio":"audio/a2/student/unit-04.mp3","lines":[["","Hello. I'm doing a survey about people's eating and cooking habits.","",5.4],["","Would you mind answering a few questions?","",9.8],["","Not at all.","",12.5],["","Great. Could I have your name first?","",14.1],["","Sure. I'm Emily Clark.","",17.3],["","And how do you spell your surname?","",20.1],["","It's C-L-A-R-K.","",22.6],["","Thank you. Let's start with breakfast.","",26.6],["","What do you normally eat in the morning?","",29.4],["","On work days, I need something quick. I used to have cereal every morning,","",31.9],["","but now I usually have yogurt with some fruit.","",37.0],["","I also drink tea, but I never have coffee.","",40.3],["","What about lunch?","",43.9],["","I work in an office, so I take my lunch with me.","",45.8],["","I normally make a sandwich at home.","",49.5],["","Sometimes I take soup instead, especially when the weather is cold.","",52.0],["","Do you enjoy cooking?","",56.8],["","Yes, very much. I usually cook dinner at around seven o'clock.","",59.0],["","I don't make anything difficult during the week because I'm tired after work.","",64.2],["","Pasta is probably the easiest thing for me to make.","",69.0],["","Do you cook every day?","",72.6],["","Almost. But on Friday evenings, I usually eat out with my sister.","",74.9],["","There's a small restaurant near her apartment that we both like.","",80.1],["","What kind of food do you order there?","",83.8],["","I often order chicken, but my favourite dish there is actually fish with rice and vegetables.","",86.3],["","My sister usually chooses pizza.","",92.6],["","Do you ever cook with other people?","",95.3],["","Yes. On Sundays, my dad and I sometimes cook together.","",97.9],["","He's really good at making bread.","",102.5],["","I normally prepare the vegetables while he works on the main dish.","",105.0],["","Is there anything you'd like to learn to make?","",109.0],["","Definitely. I'd love to learn how to make cake.","",111.9],["","I can make simple biscuits, but cakes are still difficult for me.","",115.6],["","Thanks, Emily. That's everything.","",120.3],["","You're welcome.","",122.8]]},
{"id":"sb-05","u":5,"book":"Student's Book","title":"Shopping and money","dur":120,"audio":"audio/a2/student/unit-05.mp3","lines":[["","Good afternoon. Customer services, how can I help you?","",4.9],["","Hi, I bought a jacket from your shop yesterday, but I think I need to change it.","",9.4],["","That's fine. Can I take your name first?","",15.4],["","Yes, it's Tom Harris.","",19.0],["","Could you spell your surname, please?","",21.6],["","Sure, it's H-A-R-R-I-S.","",24.7],["","Thank you. Now, what seems to be the problem with the jacket?","",30.4],["","I bought a medium, but it's too small. I tried a large one in another colour,","",35.2],["","and that fitted much better. So, I'd like a large, please.","",40.5],["","No problem. What colour did you buy?","",45.0],["","Blue. I really like it, so I don't want to change the colour. I saw a black one too,","",48.2],["","but blue looks better on me.","",54.2],["","Do you still have your receipt?","",56.5],["","Yes, I do. The jacket was £45, but there was a special offer yesterday,","",58.9],["","so I actually paid £36 for it.","",64.7],["","That's fine. You can exchange it at the shop. When would you like to come in?","",68.2],["","I'm working tomorrow, so I can't come then. I'm free on Thursday afternoon. Is that OK?","",73.5],["","Yes, we're open until 8. Do you remember which branch you bought it from?","",80.0],["","Yes. The one in the town centre, next to the big supermarket.","",85.8],["","I usually shop there because it's close to my office.","",90.1],["","Good. We currently have three large blue jackets there,","",93.4],["","so there should be one available for you.","",97.5],["","Perfect. Do I need to bring anything apart from the jacket and receipt?","",100.3],["","No. Just make sure the price label is still on the jacket.","",105.1],["","Yes, it is. I only tried the jacket on at home.","",109.8],["","Great. Then there shouldn't be any problem.","",114.0],["","Thanks for your help.","",117.3],["","You're welcome.","",119.0]]},
{"id":"sb-06","u":6,"book":"Student's Book","title":"School, learning and study","dur":130,"audio":"audio/a2/student/unit-06.mp3","lines":[["","Good morning. Welcome to Westfield Language School. How can I help you?","",5.8],["","Hi. I'd like some information about your evening English classes.","",11.1],["","Of course. I'll take a few details first. What's your name?","",16.3],["","Nina Cooper.","",21.3],["","Could you spell your surname, please?","",22.8],["","Yes. It's C-O-O-P-E-R.","",25.6],["","Thank you. Have you studied English before?","",30.8],["","Yes. I studied it at school for about four years. I can have simple conversations,","",34.5],["","but I still make quite a lot of mistakes.","",41.0],["","That's fine. You'll take a short level test before you start.","",44.1],["","Now, our evening classes are on Mondays and Wednesdays. Would both days be possible for you?","",48.3],["","Yes. I work during the day, but my evenings are usually free.","",55.0],["","Excellent. The class begins at 6 o'clock and finishes at 7.30. There's a short break in the middle.","",60.2],["","That sounds good. How many students are there in each class?","",67.8],["","We try to keep the groups small. There are usually about 10 students and the maximum is 12.","",72.3],["","Great. I find it difficult to speak when there are too many people.","",78.9],["","Then this class should suit you. The teacher spends a lot of time on conversation,","",83.7],["","but you'll also practice reading, writing and listening.","",88.6],["","Students often say that speaking is their favourite part of the course.","",92.5],["","That's exactly what I need. How much does the course cost?","",96.9],["","It's £90 a month. That includes your lessons, but you need to buy the course book separately.","",101.7],["","It costs £18.","",108.0],["","OK. And where are the evening classes held?","",110.3],["","Most lessons are upstairs, but your group will be in room 12 on the ground floor.","",114.5],["","Perfect. When can I take the level test?","",120.4],["","You can come in tomorrow afternoon, if you like.","",124.1],["","Great. I'll do that. Thank you.","",127.0]]},
{"id":"sb-07","u":7,"book":"Student's Book","title":"Jobs and Working Life","dur":124,"audio":"audio/a2/student/unit-07.mp3","lines":[["","Good morning, Park Hotel. You're calling about the weekend job, right?","",4.9],["","Yes, I saw the advertisement online yesterday and I'd like some more information.","",10.2],["","Of course. Before we start, can I take your name?","",16.1],["","It's Jamie Lewis.","",20.2],["","And could you spell your surname?","",22.4],["","Yes, it's L-E-W-I-S.","",25.1],["","Thanks. The job is in our restaurant. We're looking for someone to help the waiters and clear the tables.","",30.5],["","Have you worked in a restaurant before?","",37.4],["","No, but I worked in a cafe last summer. I served drinks and helped prepare sandwiches.","",40.1],["","That's useful experience. The restaurant gets quite busy, especially at lunchtime,","",46.6],["","so you need to work quickly.","",52.2],["","That's fine. I'm used to working with lots of customers.","",54.6],["","Good. At the moment, we need someone on Saturday and Sunday. The Saturday shift starts at 10,","",58.6],["","but on Sunday you start at 1100 because breakfast finishes later.","",65.9],["","Okay, and what time would I finish?","",71.1],["","Usually around 4. You'll get a 30-minute lunch break during the afternoon.","",74.6],["","Great. What should I wear?","",80.3],["","We provide a shirt, but you need to wear your own black trousers.","",83.3],["","Please don't wear jeans.","",88.0],["","No problem. And how much does the job pay?","",90.2],["","It's £11 an hour. You also get a free meal during each shift.","",94.1],["","That sounds good.","",99.6],["","If you're interested, you'll need to come for a short interview.","",101.4],["","We're interviewing people on Thursday afternoon.","",105.1],["","Thursday's fine. Where should I go when I arrive?","",108.4],["","Come to the main entrance and ask for Mrs Green at reception.","",112.6],["","She'll take you to the manager's office.","",116.9],["","Perfect. Thanks very much.","",119.5],["","You're welcome. See you then.","",122.0]]},
{"id":"sb-08","u":8,"book":"Student's Book","title":"Travel and Transport","dur":127,"audio":"audio/a2/student/unit-08.mp3","lines":[["","Good morning, City Travel Centre. How can I help you?","",4.7],["","Hi, I'd like some information about buses to Lakeside.","",8.6],["","I'm planning to go there this weekend.","",12.5],["","Certainly. Are you travelling alone?","",15.0],["","Yes, I'm visiting a friend who lives there.","",18.2],["","OK, before we look at the times, can I take your name?","",22.0],["","Sure, it's Alex Morgan.","",26.9],["","Could you spell your surname, please?","",29.8],["","Yes, it's M-O-R-G-A-N.","",32.7],["","Thanks. Now, which day are you planning to travel?","",38.3],["","Saturday. I thought about going on Friday evening, but I have to work late that day.","",42.9],["","No problem. There are several buses on Saturday morning.","",49.3],["","The first one leaves at 7.30, but the next bus at 8.15 is usually more convenient.","",53.1],["","Yes, 7.30 is a little early. How long does the journey take?","",60.4],["","Normally about an hour and 20 minutes. However, there are some road works this weekend,","",66.1],["","so it may take slightly longer.","",72.0],["","That's OK. How much is a return ticket?","",74.8],["","A single is £9. The return ticket is £15,","",78.3],["","so that's better value if you're coming back the same weekend.","",83.3],["","Yes, I'm returning on Sunday. Where does the bus leave from?","",87.2],["","From Central Station, but not from the main bus area.","",91.9],["","You need to go to Platform 6, which is near the cafe.","",96.2],["","OK, can I buy the ticket on the bus?","",100.2],["","You can, but weekend buses are often crowded,","",103.5],["","so I recommend booking your ticket before you travel.","",107.3],["","Good idea. Can I take a suitcase?","",111.0],["","Yes. One suitcase can go underneath the bus,","",114.3],["","and you can take a small bag with you to your seat.","",118.0],["","Perfect. I'll book the ticket online today.","",121.4],["","Great. Have a good trip.","",125.0]]},
{"id":"sb-09","u":9,"book":"Student's Book","title":"Cities, Towns and Neighbourhoods","dur":132,"audio":"audio/a2/student/unit-09.mp3","lines":[["","Hello, welcome to the new residence centre. Are you new to the area?","",5.5],["","Yes, I moved here last week, so I'm still trying to find out where everything is.","",10.7],["","Of course, I can give you some information. Can I take your name first?","",16.7],["","Sure, I'm Laura Dawson.","",21.9],["","Could you spell your surname, please?","",25.0],["","Yes, it's D-A-W-S-O-N.","",27.7],["","Thank you. And which part of town are you living in?","",33.0],["","I've got a flat in Riverside. It's quite a quiet neighbourhood, near the river.","",36.7],["","Oh, that's a nice area. There are several useful places nearby.","",42.6],["","There's a supermarket on King Street and a small market every Saturday morning.","",47.5],["","Great. I also need somewhere to exercise. Is there a gym near my flat?","",52.9],["","There is, but the sports centre is probably better. It has a gym and a swimming pool.","",59.0],["","It opens at six in the morning and closes at nine o'clock in the evening.","",65.0],["","That's perfect, because I sometimes exercise after work.","",69.5],["","You might also want to join the local library. It moved recently. It used to be next to the","",74.2],["","post office, but now it's opposite the museum.","",79.7],["","Good to know. I enjoy reading, so I'll definitely visit it.","",83.0],["","There's also a lovely park about ten minutes from Riverside.","",88.1],["","It's usually quiet during the week, although it gets quite busy on sunny weekends.","",91.9],["","I'd like somewhere to walk in the evenings.","",96.9],["","Then you'll enjoy it. There's a small lake and a café there too.","",99.9],["","Sounds great. What's the easiest way to get into the town centre?","",104.6],["","Bus number 14 goes directly from Riverside. It runs every 20 minutes during the day.","",109.8],["","Excellent. Is there anything else I should know?","",116.6],["","Yes. On Fridays, there's a street market in the main square.","",120.3],["","It's a good place to buy fresh fruit and vegetables.","",124.8],["","Thanks. This has been really helpful.","",128.2]]},
{"id":"sb-10","u":10,"book":"Student's Book","title":"Technology and Everyday Life","dur":126,"audio":"audio/a2/student/unit-10.mp3","lines":[["","Good afternoon. Tech Help Centre. How can I help you?","",5.3],["","Hi. I'm having a problem with my new tablet. I bought it from your shop last week.","",9.5],["","I'm sorry about that. I'll take a few details first. What's your name?","",15.4],["","It's Ryan Baker. Could you spell your surname, please?","",21.3],["","Sure. It's B-A-K-E-R.","",25.0],["","Thank you. Now, what exactly is wrong with the tablet?","",31.4],["","The screen is fine, and I can use most of the apps, but the camera isn't working. When I try","",35.8],["","to take a photo, the screen goes black. I see. Have you tried turning the tablet off and on again?","",41.9],["","Yes. Twice. I also charged it fully last night, but that didn't help.","",49.9],["","OK. Which model do you have?","",55.7],["","It's the T20. I nearly bought the T15 because it was cheaper, but I chose the T20 because it has","",58.7],["","more storage. Right. We can check it for you at the shop. When are you free to bring it in?","",66.0],["","I'm busy tomorrow, but I can come on Wednesday afternoon.","",73.0],["","That's fine. Our repair desk is open from 10 until 6. If you come before 4,","",77.2],["","we can probably check it the same day. Great. Do I need to bring the box?","",83.4],["","No, but please bring your receipt. We need to check when and where you bought the tablet.","",89.3],["","No problem. I still have it.","",95.6],["","Good. If it's a simple software problem, the repair should take about 30 minutes.","",98.2],["","If there's a problem inside the tablet, we may need to keep it for a few days.","",104.3],["","OK. Is there a charge for checking it?","",109.6],["","Normally it costs £20, but because your tablet is new, the check is free.","",113.3],["","Excellent. Thanks for your help.","",119.8],["","You're welcome. We'll see you on Wednesday.","",122.3]]},
{"id":"sb-11","u":11,"book":"Student's Book","title":"Health, Exercise and Sleep","dur":143,"audio":"audio/a2/student/unit-11.mp3","lines":[["","Good morning. Active Life Centre. How can I help you?","",5.7],["","Hi. I'd like to join one of your exercise classes.","",9.8],["","I want to become more active, but I'm not sure which class is best for me.","",13.5],["","No problem. I'll ask you a few questions first. What's your name?","",18.4],["","It's Daniel Price.","",23.4],["","Could you spell your surname, please?","",25.5],["","Yes. It's P-R-I-C-E.","",27.4],["","Thanks. How much exercise do you do at the moment?","",33.7],["","Not enough, really. I walk to work most days, but that only takes about 15 minutes.","",38.0],["","At weekends, I sometimes go cycling, but not regularly.","",44.0],["","OK. How are your energy levels during the day?","",48.3],["","I'm usually fine in the morning, but I often feel tired after lunch.","",52.5],["","That's one reason I want to exercise more.","",57.2],["","Exercise may help. We have a beginner fitness class that could suit you.","",60.3],["","It's on Monday and Wednesday evenings.","",65.0],["","What time does it start?","",68.1],["","The Monday class starts at 6, but Wednesday's class begins at 6.30.","",70.1],["","Wednesday would be easier, because I sometimes work late on Mondays.","",75.8],["","Great. Each class lasts 45 minutes.","",80.5],["","You'll do some simple exercises, but there's no running.","",84.1],["","Good. I'm not a big fan of running.","",88.2],["","What about sleep? How many hours do you usually get?","",91.5],["","Only about six hours. I often stay up too late watching videos, even when I have to get up early.","",96.2],["","You should try to get a little more sleep.","",103.4],["","It's also a good idea to stop using screens before bed.","",106.0],["","Yes, I know. I'm trying to leave my phone in the living room at night instead of taking it to bed.","",110.2],["","That's a good habit. Now, for the exercise class,","",116.6],["","please bring comfortable clothes and a bottle of water.","",120.6],["","Do I need special shoes?","",124.7],["","Just clean sports shoes. You'll also need a small towel,","",127.3],["","because some of the exercises can make you quite warm.","",131.2],["","Fine. How much is the class?","",135.2],["","Your first class is free, so you can try it before deciding whether to join.","",137.3]]},
{"id":"sb-12","u":12,"book":"Student's Book","title":"Sports and competitions","dur":129,"audio":"audio/a2/student/unit-12.mp3","lines":[["","Good afternoon. Westside Sports Club. How can I help?","",4.4],["","Hi. I saw a poster about your summer sports competition and I'd like to take part.","",9.7],["","Great. I can register you now. Can I have your name first?","",15.8],["","Yes. It's Oliver Kent. Could you spell your surname, please?","",21.1],["","Of course. It's K-E-N-T.","",26.4],["","Thank you. We have competitions in tennis, basketball and badminton. Which one are you interested in?","",31.4],["","I play basketball quite often, but I'm already in a competition at college. I'd like to enter the tennis competition here.","",39.4],["","No problem. Have you played tennis for long?","",47.4],["","About three years. I usually play with my brother at weekends. I'm not an excellent player but I really enjoy it.","",50.4],["","That's the important thing. The competition is on Saturday the 18th. It was originally planned for Sunday that we had to change the day.","",58.4],["","Saturday is fine. What time does it start?","",68.4],["","The first matches begin at 10, but all players must arrive by 9.30. That gives us enough","",72.4],["","time to check everyone's names and explain the rules.","",79.3],["","OK, do I need to bring my own equipment?","",83.0],["","We provide tennis balls, but you should bring your own racket. We have a few spare ones,","",86.7],["","but they're mainly for emergencies.","",92.5],["","That's fine. How much is it to enter?","",94.6],["","The normal price is £12, but club members pay only £8.","",98.3],["","I joined the club last month, so I can pay the lower price, right?","",104.2],["","Exactly! There will also be water and fruit for all the players.","",108.6],["","Great! Where should I go when I arrive?","",113.7],["","Go to the main sports hall and ask for Martin. He'll show you which court you're playing","",117.5],["","on.","",122.6],["","Perfect! I'm looking forward to it!","",123.6],["","Excellent! Good luck!","",126.3]]},
{"id":"sb-13","u":13,"book":"Student's Book","title":"Weather and seasonal activities","dur":127,"audio":"audio/a2/student/unit-13.mp3","lines":[["","Good morning. Green Valley Activity Centre. How can I help?","",6.0],["","Hi. My family is visiting Green Valley next weekend and I'd like some information about","",10.6],["","your outdoor activities. Of course. I can help with that. Could I take your name first?","",16.7],["","Yes, it's Megan Frost. Could you spell your surname, please?","",23.8],["","Sure. It's F-R-O-S-T.","",29.4],["","Thank you. What kind of activity are you interested in?","",34.3],["","We wanted to go cycling, but I checked the weather this morning and it looks quite wet.","",38.3],["","Is there anything else we could do?","",43.9],["","Yes. The forecast says there will be rain on Saturday morning,","",46.4],["","but the afternoon should be much drier.","",50.7],["","That's good. We'd still like to spend some time outside.","",53.5],["","In that case, you could join our afternoon forest walk.","",57.7],["","It starts at 2.30 and lasts about two hours.","",61.2],["","That sounds nice. Is it suitable for children?","",65.1],["","Yes. The route is easy and families often join us.","",69.1],["","However, the paths can be wet at this time of year,","",73.2],["","so everyone should wear boots rather than ordinary shoes.","",76.6],["","OK. We can bring those. What about Sunday?","",80.6],["","Sunday should be sunny, although it may be a little cold in the morning.","",84.8],["","It should reach about 16 degrees in the afternoon.","",89.3],["","Great. Maybe we could go cycling then?","",92.8],["","Definitely. We rent bicycles here.","",96.2],["","An adult bicycle costs £12 for the day and a child's bicycle costs £8.","",99.0],["","Perfect. Do we need to book them?","",105.4],["","At weekends, yes. Spring is a very popular time for cycling here,","",108.4],["","especially when the weather is good.","",113.3],["","OK. I'll book them today.","",115.6],["","Great. And remember to bring a light jacket,","",118.2],["","because the evenings can still be cool.","",121.1],["","We will. Thanks for your help.","",124.3]]},
{"id":"sb-14","u":14,"book":"Student's Book","title":"Animals and Wildlife","dur":125,"audio":"audio/a2/student/unit-14.mp3","lines":[["","Good morning, Greenhill Wildlife Park","",4.0],["","how can I help? Hi, I'm planning to visit the park with my family this weekend","",7.9],["","and I'd like some information. Of course","",13.6],["","are you interested in any particular animals? My children really want to see","",16.9],["","the monkeys","",22.4],["","but I'd like to see everything if we have enough time.","",23.3],["","Certainly. Before we continue could I take your name?","",27.1],["","Yes, I'm Helen Webb. Could you spell your surname please?","",30.8],["","Sure, it's W-E-B-B.","",36.1],["","Thank you. Which day are you thinking of visiting?","",40.3],["","We're coming on Sunday. We originally planned to come on Saturday","",43.9],["","but my son has a football match. No problem.","",48.5],["","The park opens at nine. If your children like monkeys","",51.8],["","there's a feeding session at 10.30. A member of staff talks about the animals","",55.6],["","while they eat.","",60.2],["","They'll love that! Where are the monkeys?","",61.0],["","They're in the forest area just past the lake.","",64.5],["","You'll also see several kinds of birds there. Some of them are very colourful","",67.8],["","so it's a popular place for photographs. Great!","",73.0],["","Are there any baby animals at the moment? Yes","",76.8],["","we have two young bears. They were born earlier this year","",80.9],["","and have recently started coming outside with their mother.","",84.9],["","Wonderful! My children will be excited about those.","",88.4],["","There's also a short wildlife talk in the afternoon.","",93.2],["","It starts at two and explains how we care for the animals.","",96.5],["","Is there somewhere to eat? Yes.","",100.7],["","The cafe is next to the main entrance. You can also bring your own food","",103.8],["","and use the picnic area near the river. Good!","",108.2],["","How much are children's tickets? Adults are 14 pounds","",111.9],["","and a child's ticket is nine pounds. Children under three","",116.4],["","enter free. Perfect! Thanks for all the information.","",120.6]]},
{"id":"sb-15","u":15,"book":"Student's Book","title":"Nature and the Environment","dur":128,"audio":"audio/a2/student/unit-15.mp3","lines":[["","Hello, Green Town Project. How can I help?","",3.9],["","Hi, I saw your poster about the community clean-up and I'd like to join.","",9.0],["","That's great. We're still looking for volunteers. Can I take your name first?","",14.6],["","Yes, I'm Ben Russell. Could you spell your surname, please?","",20.5],["","Sure. It's R-U-S-S-E-L-L.","",26.2],["","Thank you. We're cleaning several outdoor areas this month.","",32.0],["","The next event is at Lakewood Park. Have you been there before?","",36.2],["","Yes. I sometimes go there for walks. It's a beautiful place.","",40.6],["","But I noticed quite a lot of rubbish near the lake last weekend.","",45.4],["","That's one of the reasons we chose it. We're meeting this Saturday.","",49.7],["","We considered Sunday, but the park is usually much busier then.","",54.0],["","Saturday is fine. What time should I arrive?","",58.6],["","We'll start cleaning at ten, but volunteers should arrive by nine forty-five.","",62.0],["","That gives us time to explain what everyone needs to do.","",67.4],["","Okay. Do I need to bring anything?","",71.0],["","We provide rubbish bags and gloves. Please bring a bottle of water and wear comfortable clothes.","",74.2],["","Strong shoes are also a good idea because the ground near the lake can be muddy.","",80.6],["","No problem. What kind of rubbish do you usually find?","",86.0],["","Mostly plastic bottles, paper and food packaging.","",90.3],["","We separate everything we collect so that as much as possible can be recycled.","",94.4],["","That makes sense. How long will the clean-up take?","",99.8],["","About three hours. At one o'clock we'll stop and have lunch together.","",103.6],["","We provide sandwiches, but volunteers should bring their own drink.","",108.4],["","Great. Can children take part too?","",112.8],["","Yes, but anyone under sixteen needs to come with an adult.","",116.2],["","Perfect. I might bring my younger brother.","",121.4],["","Excellent. The more people we have, the better.","",124.3]]},
{"id":"sb-16","u":16,"book":"Student's Book","title":"Films, music, books and entertainment","dur":127,"audio":"audio/a2/student/unit-16.mp3","lines":[["","Good afternoon. Central Arts Centre. How can I help?","",6.8],["","Hi. I saw a poster about your film and music weekend and I'd like some more information.","",11.1],["","Of course. Are you interested in booking something?","",18.1],["","Yes, probably. I'm coming with a friend.","",22.0],["","Great. Before we start, can I take your name?","",26.0],["","Sure. I'm Amy Stone.","",29.9],["","Could you spell your surname, please?","",32.6],["","Yes. It's S-T-O-N-E.","",35.5],["","Thank you. The festival starts on Friday evening, but most activities are on Saturday.","",40.7],["","There are films, live music and a book event.","",46.6],["","Saturday is better for us. What films are you showing?","",50.3],["","There's a comedy in the afternoon and an adventure film in the evening.","",54.3],["","The comedy starts at 2, but the adventure film begins at 6.30.","",58.6],["","I think we'd prefer the adventure film.","",63.5],["","That's been very popular. It's about a group of friends who travel across South America","",66.6],["","looking for a lost village.","",71.8],["","Sounds interesting. Is there any live music?","",74.0],["","Yes. After the film, a local band will play in the main hall.","",77.8],["","They mostly play pop and rock music.","",82.1],["","Great. What about the book event you mentioned?","",85.1],["","A travel writer called James Wood is giving a short talk.","",88.8],["","He'll speak about his new book and answer questions from the audience.","",92.8],["","I'd like that too. How much are tickets?","",97.3],["","You can buy separate tickets, but the full day ticket is better value.","",100.8],["","It used to be £20, but this year it costs £18.","",105.3],["","That sounds reasonable. Do we need to book in advance?","",110.1],["","I recommend it. Last year, the evening events were completely full by Friday morning.","",114.2],["","Okay. I'll book two tickets online tonight.","",120.4],["","Excellent. I hope you both enjoy the festival.","",124.1]]},
{"id":"sb-17","u":17,"book":"Student's Book","title":"Interesting people and their lives","dur":123,"audio":"audio/a2/student/unit-17.mp3","lines":[["","Welcome back to People in Our Town. Today I'm","",4.5],["","talking to a young photographer who has travelled to many interesting places. Thanks for joining us.","",9.0],["","Could you introduce yourself? Sure. My name is Nina Hayes.","",14.7],["","And could you spell your surname for our listeners? Of course. It's H-A-Y-E-S.","",20.0],["","Thanks Nina. Where did you grow up?","",27.9],["","I was born in London, but my family moved when I was very young. I actually grew up in a small village near Oxford. There were only about 500 people there.","",31.9],["","When did you become interested in photography?","",42.9],["","When I was 14, my grandfather gave me his old camera for my birthday. At first I just took pictures of my family and friends.","",45.9],["","Did you study photography later?","",54.9],["","Yes. After school, I studied art at college for two years. I wanted to study painting at first, but I decided to choose photography because I enjoyed it more.","",57.9],["","And when did you start travelling?","",69.9],["","My first big trip was to Italy. I stayed there for three months and took hundreds of pictures. After that, I visited several other countries.","",71.9],["","Which place has been your favourite?","",82.9],["","Probably Japan. I spent six weeks there last year.","",84.9],["","I loved the busy cities, but I also visited some beautiful quiet places in the countryside.","",89.9],["","What do you photograph most often now?","",96.9],["","I used to take lots of pictures of buildings, but these days I mainly photograph people.","",99.9],["","I enjoy meeting someone and learning a little about their life before taking their picture.","",105.9],["","Do you have any plans for the future?","",111.9],["","Yes. Next year I want to make a book of my favourite photographs.","",114.9],["","That sounds exciting. Good luck with it.","",119.9]]},
{"id":"sb-18","u":18,"book":"Student's Book","title":"Festivals, Celebrations and Traditions","dur":126,"audio":"audio/a2/student/unit-18.mp3","lines":[["","Good morning, Riverside Festival Office.","",5.3],["","How can I help? Hi, my family has just moved to the area","",9.0],["","and we'd like some information about the Summer Festival.","",13.8],["","Of course, it's one of our biggest celebrations of the year.","",17.0],["","Can I take your name first? Yes,","",21.1],["","I'm Anna Mitchell. Could you spell your surname please?","",24.6],["","Sure, it's M-I-T-C-H-E-L-L.","",29.4],["","Thank you. The festival is usually held on the first Saturday in July,","",36.6],["","but this year it will be on Sunday because there's another large event on Saturday.","",41.5],["","Great! What time does everything begin?","",46.6],["","The market opens at 10, but the main celebration starts at 11.30 with a parade through the town centre.","",50.2],["","My children would enjoy that. What happens after the parade?","",57.7],["","There's live music in Riverside Park. We'll also have traditional dancing,","",62.2],["","games for children and plenty of food.","",67.0],["","What kind of traditional food can we try?","",70.2],["","Several things, but our local bread is especially popular.","",73.5],["","It's made fresh in the morning and visitors can watch how it's prepared.","",77.8],["","That sounds interesting. Do people wear anything special?","",82.2],["","Some of the dancers wear traditional clothes. Visitors can wear whatever they like,","",86.8],["","although many people choose something colourful because it makes the festival feel more cheerful.","",92.2],["","Is there anything in the evening? Yes. At seven there's a concert,","",97.7],["","and later there will be fireworks near the river. They begin when it gets dark.","",102.8],["","Do we need tickets? Most activities are free.","",108.2],["","The evening concert costs £5 for adults, but children can enter free.","",112.1],["","Perfect! We'll definitely come.","",117.4],["","Wonderful! I hope your family enjoys its first Riverside Festival.","",120.5]]},
{"id":"sb-19","u":19,"book":"Student's Book","title":"Childhood and Memories","dur":119,"audio":"audio/a2/student/unit-19.mp3","lines":[["","Welcome to Memories of Home. Today we're talking to people","",4.6],["","about their childhood. Could you introduce yourself? Sure. My name's Rachel Perry.","",9.2],["","Could you spell your surname for us? Yes, it's P-E-R-R-Y. Thanks, Rachel. Where did you grow up?","",16.3],["","I grew up in a small town near the sea. It wasn't a very busy place,","",26.7],["","but I loved living there because we could walk to the beach.","",32.1],["","What was your home like?","",35.3],["","We lived in an old house with a large garden. I shared a bedroom with my younger sister until","",37.9],["","I was 12. We sometimes argued because she was untidy, but we were very close.","",44.7],["","What do you remember about school?","",50.2],["","I went to a small primary school about 15 minutes from our house.","",53.2],["","I usually walked there with two friends.","",58.2],["","My favourite subject was art because I loved drawing and making things.","",61.2],["","What did you do after school?","",66.2],["","We spent a lot of time outside.","",69.2],["","There weren't many computer games in our house,","",71.2],["","so my friends and I usually played in the garden or rode our bikes around the neighbourhood.","",74.2],["","Did your family have any special weekend routines?","",79.2],["","Yes, every Saturday morning my dad took us to the market.","",83.2],["","In the afternoon we often visited my grandparents.","",88.2],["","My grandmother always made cake for us.","",91.2],["","That sounds like a nice memory.","",94.2],["","What about holidays?","",97.2],["","Every summer we went camping for a week.","",99.2],["","My favourite trip was when I was 14.","",102.2],["","We stayed near a lake and I learnt to swim there.","",105.2],["","Do you still visit the town where you grew up?","",108.2],["","Yes, usually once or twice a year. It has changed a lot, but it still feels like home.","",111.2]]},
{"id":"sb-20","u":20,"book":"Student's Book","title":"Everyday problems and solutions","dur":129,"audio":"audio/a2/student/unit-20.mp3","lines":[["","Good morning. West Park Apartments. How can I help you?","",6.0],["","Hi. I live in one of your apartments and I need to report a problem.","",9.8],["","Of course. Can I take your name first?","",15.4],["","Yes. I'm Emma Walsh.","",18.7],["","Could you spell your surname, please?","",21.6],["","Sure. It's W-A-L-S-H.","",24.4],["","Thank you. And which apartment are you in?","",29.3],["","Apartment 24 on the second floor. I moved in about three months ago.","",32.9],["","Okay. What seems to be the problem?","",38.8],["","There's something wrong with the shower. The water was fine yesterday morning,","",42.1],["","but last night it suddenly became cold. I tried it again this morning and it's still cold.","",46.8],["","I see. Is there hot water anywhere else in the apartment?","",54.2],["","Yes. The kitchen tap is working normally, so I think the problem is only in the bathroom.","",58.9],["","All right. We'll need to send someone to look at it. Are you at home today?","",66.1],["","I'm at work until five. I could be home by five thirty, but not before then.","",71.3],["","That should be fine. Our repair person can come between five thirty and seven.","",77.5],["","Great. Will I need to pay anything?","",83.2],["","No. Bathroom repairs like this are free for residents, unless the problem was caused by damage.","",86.4],["","Okay. That's good.","",92.9],["","Is there anything else you'd like us to check?","",95.4],["","Actually, yes. The light in the kitchen is also very weak. I changed the bulb,","",98.2],["","but it didn't make any difference.","",104.5],["","I'll add that to the repair request. The repair person can check both problems.","",107.1],["","Perfect. What should I do if I'm late getting home?","",112.5],["","Call the office on seven three oh four one eight six. Someone will be here until seven.","",117.0],["","Great. I'll write that down. Thanks for your help.","",123.6],["","You're welcome.","",127.4]]},
{"id":"sb-21","u":21,"book":"Student's Book","title":"Helping people and community life","dur":129,"audio":"audio/a2/student/unit-21.mp3","lines":[["","Good morning, Brookside Community Centre. How can I help?","",6.2],["","Hi, I saw your notice asking for volunteers and I'd like to help.","",10.3],["","That's great. We have several volunteer activities at the moment. Can I take your name first?","",15.9],["","Sure, I'm Alice Young.","",22.3],["","Could you spell your surname, please?","",25.0],["","Yes, it's Y-O-U-N-G.","",27.8],["","Thank you. What kind of volunteer work are you interested in?","",33.0],["","I enjoy working with older people. I used to visit my grandmother every week and I often","",37.3],["","helped her with shopping and things around the house.","",43.3],["","Then our shopping service might suit you. Volunteers help older residents who find it","",46.6],["","difficult to carry heavy bags home.","",51.7],["","That sounds like something I could do.","",54.4],["","Good. We need volunteers on Tuesday and Thursday afternoons. Tuesday's almost full,","",57.0],["","so Thursday would be more useful for us.","",62.8],["","Thursday is fine. I finish work early that day.","",65.9],["","Excellent. Volunteers meet here at the community centre at 2.15. We give everyone a shopping","",70.0],["","list and an address before they leave.","",76.3],["","How long does it usually take?","",79.8],["","About two hours. Most volunteers help one or two people each afternoon.","",82.4],["","Do I need a car?","",88.2],["","No. All the homes are nearby. Most volunteers walk, although some people use bicycles.","",90.2],["","Great. Is there anything I should bring?","",96.9],["","We provide shopping bags, but please bring a phone in case you need to contact the centre","",100.1],["","while you're out.","",105.0],["","OK. Is there any training before I start?","",106.7],["","Yes. Just a short meeting. The next one is on Monday evening and lasts about 40 minutes.","",110.6],["","Perfect. I can come to that.","",117.5],["","Wonderful. We really appreciate your help.","",120.2],["","The service is very important to people in the neighbourhood.","",123.4],["","I'm happy to help.","",127.1]]},
{"id":"sb-22","u":22,"book":"Student's Book","title":"Trying something new","dur":138,"audio":"audio/a2/student/unit-22.mp3","lines":[["","Good afternoon. Adventure club, how can I help?","",5.2],["","Hi, I saw your advertisement for beginner activities.","",9.1],["","I'd like to try something new, but I'm not sure which activity to choose.","",13.3],["","No problem. Can I take your name first?","",18.9],["","Yes, I'm Jessica Miles.","",22.2],["","Could you spell your surname, please?","",25.2],["","Sure. It's M-I-L-E-S.","",28.0],["","Thank you. Have you done any adventure sports before?","",33.1],["","Not really. I go swimming sometimes and I ride my bike at weekends,","",37.0],["","but I've never tried anything very exciting.","",42.5],["","Well, we have several activities for beginners.","",45.8],["","You could try climbing, kayaking or horse riding.","",48.9],["","I'm a little afraid of heights, so climbing probably isn't for me.","",53.1],["","I think kayaking sounds the most interesting.","",58.1],["","Good choice. Our beginner kayaking sessions take place at Blue Lake.","",61.4],["","You don't need any previous experience.","",66.0],["","Great. When are the sessions?","",69.0],["","We have them on Saturday and Sunday mornings.","",71.6],["","Saturday is nearly full this week, so the other day would be better.","",74.6],["","Sunday is fine. What time does it start?","",79.0],["","The activity starts at 10, but everyone needs to arrive by 9.30.","",82.6],["","The instructor will explain the safety rules before you go onto the water.","",87.4],["","Okay. Do I need to bring any special equipment?","",91.8],["","We provide the kayak, helmet and life jacket.","",95.8],["","You should bring a towel and some dry clothes because you may get wet.","",99.1],["","I expected that. How long does the session last?","",103.6],["","About two hours. There's a short break halfway through.","",107.8],["","And how much does it cost?","",112.2],["","The normal price is £25, but your first beginner session costs £18.","",114.6],["","That sounds good. I'd like to book it.","",120.9],["","Excellent. One final thing. The water can be quite cold, even in summer,","",124.0],["","so wearing warm clothes is a good idea.","",129.8],["","Thanks. I'm a little nervous, but I'm excited to try it.","",133.3]]},
{"id":"sb-23","u":23,"book":"Student's Book","title":"Interesting places and different cultures","dur":128,"audio":"audio/a2/student/unit-23.mp3","lines":[["","Good morning. World Travel Club. How can I help?","",6.4],["","Hi. I saw your poster about the International Culture Day and I'd like some information.","",10.2],["","Of course. Can I take your name first?","",16.6],["","Yes. I'm Lucy Warren.","",19.8],["","Could you spell your surname, please?","",22.7],["","Sure. It's W-A-R-R-E-N.","",25.4],["","Thank you. Culture Day is a chance to learn about different countries through food, music, clothes and activities.","",30.0],["","This year, the main country is Japan.","",38.0],["","That's great! I've always wanted to visit there. What activities will you have?","",41.0],["","There are several. In the morning, a traveller will give a talk about Japanese cities and everyday life.","",47.0],["","It starts at 10.30 in the main hall.","",54.0],["","That sounds interesting. I'd like to hear about what daily life is really like there.","",57.0],["","After the talk, there's a short language lesson. You can learn some simple greetings and useful words.","",63.0],["","Nice. What happens in the afternoon?","",70.0],["","At one o'clock, there's a cooking demonstration. The chef will show visitors how to prepare a traditional rice dish. Everyone can taste it afterwards.","",73.0],["","afterwards.","",83.0],["","Excellent! I love trying food from other countries.","",84.0],["","There's also a display of traditional clothes. Some visitors can try them on and take photographs.","",88.0],["","Do you have any music?","",95.0],["","Yes. A group of musicians will perform at three. They use traditional drums so the performance can be quite loud.","",97.0],["","Sounds fun! How much does Culture Day cost?","",105.0],["","Adult tickets are normally £12, but students pay £8 if they bring a student card.","",110.0],["","Perfect! I'm a student. Where is the event?","",116.3],["","At the International Centre on Park Street, opposite the Museum.","",120.7],["","Great! I'll definitely come.","",124.8]]},
{"id":"sb-24","u":24,"book":"Student's Book","title":"Life in the past and life today","dur":130,"audio":"audio/a2/student/unit-24.mp3","lines":[["","Welcome to Then and Now. Today we're talking about how everyday life has changed.","",6.2],["","Could you introduce yourself? Of course. I'm Margaret Hill.","",12.2],["","Could you spell your surname, please? Yes, it's H-I-L-L.","",17.3],["","Thank you. Margaret, where did you grow up?","",24.6],["","I grew up in a small village. There were only a few shops and everybody seemed to know each other.","",27.8],["","How did you usually get to school?","",34.5],["","I normally walked. The school was about two kilometres from our house.","",37.1],["","My brother and I went together, even when the weather was bad.","",42.3],["","Did your family have a television?","",46.2],["","Yes, but only one. We got our first television when I was about ten.","",49.1],["","It was quite small and there weren't many programs to choose from.","",55.0],["","That's very different from today. What did you do for entertainment?","",60.0],["","We spent much more time outside. After school we played games in the street or rode our bikes.","",65.0],["","In the evening I often read books or listened to the radio.","",72.0],["","What about shopping?","",76.0],["","My mother went to the local shops almost every day because we didn't have a big fridge.","",78.0],["","There was no supermarket nearby.","",84.0],["","Today I usually go shopping only once a week.","",87.2],["","How did people keep in touch with friends and family?","",91.3],["","We wrote letters or used the telephone at home.","",94.9],["","Calls were quite expensive so we didn't stay on the phone for very long.","",98.7],["","Which do you prefer?","",103.5],["","Life then or life today?","",105.0],["","Some things were nicer in the past because people spent more time together, but everyday","",108.0],["","life is certainly easier today. I can speak to my grandchildren online, buy things from","",113.2],["","home and find information in seconds.","",118.8],["","So technology has made a big difference.","",122.7],["","Definitely. I wouldn't want to give up the internet now.","",125.8]]},
{"id":"wb-01","u":1,"book":"Workbook","title":"Daily routines and habits","dur":129,"audio":"audio/a2/workbook/unit-01.mp3","lines":[["","Hello. I'm asking people about their daily habits for our college project.","",5.3],["","Could I ask you some questions?","",10.3],["","Of course.","",12.6],["","Thanks. First, what's your name?","",13.9],["","I'm Daniel Brooks.","",17.7],["","And could you spell your surname for me?","",19.8],["","Yes, it's B-R-O-O-K-S.","",22.7],["","Great. Let's start with your morning routine. Do you get up early?","",27.8],["","Yes, because I start work quite early. My alarm rings at 6.20 and I usually get up 10 minutes later","",33.3],["","at 6.30. I wash my face, get dressed and then make breakfast.","",40.8],["","What do you normally have?","",46.4],["","I usually have toast with cheese. I sometimes have eggs at the weekend,","",48.5],["","but they take too long on work days. I always drink a glass of juice with breakfast.","",53.3],["","How do you get to work?","",59.5],["","I usually cycle. I bought a new bicycle last year and I really enjoy riding it.","",61.6],["","If the weather is bad, I take the bus instead.","",67.4],["","And what time do you start work?","",70.8],["","At 8 o'clock. I work in a small hotel so mornings can be quite busy.","",73.4],["","I have lunch at about 12.30, usually in the staff room.","",78.8],["","What do you do when you finish work?","",83.4],["","I finish at 4. On Thursdays, I meet my brother and we play tennis in the park.","",85.9],["","On other weekdays, I normally go home and relax.","",91.4],["","Do you cook in the evening?","",95.3],["","Most days. I usually make something simple because I don't like spending hours in the kitchen.","",97.6],["","After dinner, I often listen to music or watch a film.","",103.7],["","What about bedtime?","",108.1],["","I usually go to bed at 10.30, but I don't fall asleep immediately.","",110.2],["","I normally read a few pages of a book first.","",115.1],["","And do you follow the same routine at weekends?","",118.7],["","Not at all. On Sunday mornings, I sleep longer and usually go for a walk after breakfast.","",122.3]]},
{"id":"wb-02","u":2,"book":"Workbook","title":"Family, Friends and Relationships","dur":129,"audio":"audio/a2/workbook/unit-02.mp3","lines":[["","Hello. I'm doing a short project about the people who are important in our lives.","",6.1],["","Would you mind answering a few questions? No, that's fine.","",11.7],["","Thanks. Let's start with your name. I'm Oliver Reed.","",16.3],["","Is that R-E-A-D? No, it's R-E-E-D.","",21.6],["","Got it. Now, Oliver, who do you live with?","",26.9],["","I live with my mum, my dad and my older sister, Hannah. She's 23.","",32.2],["","She used to live away from home when she was at university, but she moved back last summer.","",37.8],["","Do you and Hannah get on well?","",43.2],["","Most of the time. She's very helpful, and I can talk to her when I have a problem.","",45.7],["","We have different interests, though. She loves reading, while I prefer playing computer games.","",50.8],["","Do you do anything together?","",57.2],["","Yes. We both enjoy cooking, so on Sunday evenings we usually make dinner for our parents.","",59.7],["","Last Sunday we made chicken and rice.","",66.1],["","Is there anyone else in your family you see regularly?","",68.9],["","My uncle lives nearby. He has two young children, so I sometimes look after them.","",72.6],["","I usually help on Friday afternoons when he's still at work.","",78.1],["","Now, tell me about your friends.","",82.4],["","My closest friend is Sam. We first met at a football club about six years ago.","",85.3],["","He doesn't play football anymore, but we still spend a lot of time together.","",91.0],["","What's Sam like?","",95.7],["","He's quiet when you first meet him, but he's very kind. He's also patient,","",97.5],["","which is useful because I'm sometimes a little impatient.","",102.6],["","How often do you see him?","",107.1],["","Usually twice a week. We meet at the library on Wednesday because we're both studying for exams.","",109.4],["","At the weekend, we sometimes play basketball or go out for lunch.","",115.5],["","And how do you keep in touch on other days?","",120.2],["","Mostly by text. We rarely phone each other because messaging is easier.","",123.2]]},
{"id":"wb-03","u":3,"book":"Workbook","title":"Hobbies and Free Time","dur":132,"audio":"audio/a2/workbook/unit-03.mp3","lines":[["","Hello, I'm asking students about their hobbies for our college website. Can I ask you a few questions?","",4.8],["","Sure.","",12.5],["","Thanks. Can I start with your name?","",13.8],["","Yes, I'm Leo Martin.","",17.4],["","Sorry, how do you spell your surname?","",20.5],["","It's M-A-R-T-I-N.","",23.6],["","Thank you. So, Leo, what do you usually do when you have some free time?","",27.3],["","I really enjoy being outdoors. My main hobby is cycling. I sometimes ride around town,","",34.5],["","but at weekends I prefer going into the countryside because the roads are quieter.","",41.0],["","Do you go cycling every weekend?","",46.6],["","Almost. I normally go on Sunday morning. I used to go on Saturdays,","",49.3],["","but I started working at a café on Saturday mornings about three months ago.","",54.6],["","Do you cycle alone?","",59.5],["","Sometimes, but I usually go with my cousin. We leave home quite early, usually at about 8.30,","",61.7],["","because there aren't many cars on the road then.","",68.7],["","We normally ride for two hours and stop somewhere for a drink.","",71.3],["","What do you do when the weather is bad?","",75.9],["","Then I stay indoors. I'm learning to play the guitar at the moment.","",78.7],["","I'm still a beginner, so I practice simple songs.","",83.0],["","I try to practice several times during the week.","",86.6],["","Do you have any other hobbies?","",90.2],["","Yes. I like playing chess. There's a small club at my college,","",92.6],["","and we meet every Wednesday after classes. I'm not the best player there,","",97.1],["","but it's fun, and I'm getting better.","",101.7],["","How do you usually relax in the evening?","",104.4],["","I sometimes watch films, but I spend more time listening to podcasts.","",107.7],["","I like ones about travel, because I enjoy learning about different countries.","",112.7],["","Is there a hobby you'd like to try in the future?","",117.5],["","I'd like to try fishing. My uncle goes quite often,","",121.2],["","and he says he'll take me with him this summer.","",124.7],["","Great. Thanks, Leo.","",127.8],["","No problem.","",130.1]]},
{"id":"wb-04","u":4,"book":"Workbook","title":"Food, Cooking and Eating","dur":138,"audio":"audio/a2/workbook/unit-04.mp3","lines":[["","Hi, I'm collecting information about how people cook and eat at home.","",5.5],["","Could I ask you a few questions? Sure.","",10.7],["","Thanks. Can I have your name first? Yes, I'm Adam Foster.","",14.6],["","Sorry, could you spell your surname? Of course, it's F-O-S-T-E-R.","",21.3],["","Great. Adam, do you usually have a big breakfast?","",28.5],["","Not really. I'm often in a hurry in the morning. I used to eat just a banana,","",34.6],["","but these days I normally make toast and have it with some cheese. I drink a glass of water too.","",39.6],["","What about lunch? Do you cook something?","",46.4],["","No, because I'm at college during the day. There's a café next to the library. I usually buy lunch","",49.9],["","there at about one o'clock. The sandwiches are good, but I normally choose soup because it's cheaper.","",55.8],["","How much does lunch usually cost?","",62.2],["","The soup used to be £4, but it went up recently. It now costs £5.","",65.1],["","A sandwich is about £6, so I still save some money.","",71.0],["","Do you cook in the evening?","",75.3],["","Yes. I share a flat with my friend Ben, and we take turns cooking.","",77.6],["","I cook on Mondays, Wednesdays and Saturdays. Ben cooks on the other days.","",82.4],["","What are you good at making?","",88.2],["","I make a really good masala. It's quite simple. I use potatoes, onions, tomatoes and some spices.","",90.4],["","Ben prefers my pasta, but curry is my favourite.","",98.2],["","Do you ever invite people for dinner?","",102.6],["","Sometimes. We usually invite a few friends once a month.","",105.4],["","Everyone brings something, so we don't have to prepare all the food ourselves.","",109.5],["","What do you usually bring when someone else invites you?","",114.2],["","I normally bring juice or something sweet. I'm terrible at making desserts,","",118.2],["","so I usually buy them from a shop.","",123.1],["","Is there anything you want to learn to cook?","",125.7],["","Yes. Bread. My grandmother makes amazing bread, and I'd like her to teach me.","",128.6],["","Great. Thanks for your time.","",135.0]]},
{"id":"wb-05","u":5,"book":"Workbook","title":"Shopping and money","dur":127,"audio":"audio/a2/workbook/unit-05.mp3","lines":[["","Good morning. Green Street Market. How can I help?","",4.7],["","Hi. I'm calling about the weekend market. I'd like to sell some things there on Saturday.","",8.5],["","Of course. I just need to take a few details. What's your name?","",15.0],["","Rachel King.","",20.4],["","Could you spell your surname, please?","",21.9],["","Yes. It's K-I-N-G.","",24.7],["","Thank you. And what are you planning to sell?","",29.4],["","Mostly clothes. I have some jackets and t-shirts that I don't wear anymore.","",33.3],["","I also have a few books, but I think clothes will be the main thing.","",38.8],["","That's fine. You'll need to rent a table. We have small and large ones available.","",43.7],["","How much are they?","",50.4],["","A large table is £15 for the day. The small one used to cost £8, but from this month,","",52.1],["","it's £10. I think the small one will be enough.","",59.4],["","OK. The market opens to customers at 10, but sellers need to arrive earlier.","",64.4],["","Please be there by 9.15, so you have time to prepare your table.","",70.6],["","That's fine. Where exactly is the market?","",75.5],["","It's in Green Street Hall. Do you know the building?","",79.0],["","I know Green Street, but I'm not sure about the hall.","",83.0],["","It's opposite the bank. There's a café on one side and a pharmacy on the other,","",87.3],["","so it's quite easy to find.","",92.8],["","Great. Can customers pay by card?","",95.4],["","Some sellers accept cards, but you would need your own card machine.","",98.7],["","Most people bring cash, especially for cheaper things.","",103.4],["","OK. I'll remember that.","",107.4],["","One more thing. Sellers must bring their own bags for customers.","",109.8],["","We provide the tables and chairs, but not bags.","",114.4],["","No problem. I have plenty at home.","",118.4],["","Excellent. We'll see you on Saturday.","",121.5],["","Thanks. Bye.","",124.8]]},
{"id":"wb-06","u":6,"book":"Workbook","title":"School, Learning and Study","dur":132,"audio":"audio/a2/workbook/unit-06.mp3","lines":[["","Hello, City Study Centre, how can I help?","",4.3],["","Hi, I'm interested in your weekend computer course.","",9.1],["","I saw a poster about it at my college. Certainly,","",13.4],["","I can give you some information. First, can I take your name?","",17.2],["","Yes, it's Marcus Hill.","",21.4],["","Could you spell your surname? Of course,","",24.6],["","it's H-I-L-L.","",28.8],["","Thanks. Have you done a computer course before?","",32.5],["","No, but I use a computer every day for my studies.","",36.5],["","I can type and find information online, but I'd like to learn more.","",40.7],["","Then the beginner course should be suitable.","",45.7],["","Classes are on Saturday mornings.","",48.4],["","We used to have a Sunday class too, but that isn't running this term.","",50.8],["","Saturday is perfect. What time does it start?","",55.8],["","The building opens at 9, but the lesson begins at 9.30.","",59.7],["","Each lesson lasts two hours.","",64.4],["","OK, what do students learn?","",67.2],["","During the first few weeks, you'll learn how to create documents and organise files.","",70.2],["","Later, you'll learn to make simple presentations.","",75.9],["","There's also a lesson about using the internet safely.","",79.5],["","That sounds useful. Do I need to bring my own computer?","",83.2],["","No. Every student can use one of our computers.","",87.4],["","You should bring a notebook though, because the teacher gives lots of useful tips.","",91.3],["","Fine. How much is the course?","",96.5],["","The full course is £75. It was £85 last term, so it's a little cheaper now.","",99.3],["","Good. Where exactly is the study centre?","",107.5],["","We're on King Road, opposite the library.","",111.0],["","Your lessons will be in room 8, which is on the first floor.","",114.0],["","Great. Can I register online?","",118.2],["","Yes. Or you can come to the centre and complete a form here.","",121.1],["","I think I'll do it online tonight.","",126.4],["","Perfect. We hope to see you soon.","",128.9]]},
{"id":"wb-07","u":7,"book":"Workbook","title":"Jobs and Working Life","dur":130,"audio":"audio/a2/workbook/unit-07.mp3","lines":[["","Good afternoon. Bright office services. How can I help?","",5.1],["","Hi. I'm calling about the part-time office job you advertised.","",9.2],["","Of course. Can I take your name first?","",13.8],["","Yes. It's Maya Evans.","",17.2],["","Could you spell your surname, please?","",20.3],["","Sure. It's E-V-A-N-S.","",23.1],["","Thank you. The job is for an office assistant. Have you done office work before?","",28.0],["","A little. Last year I worked in my uncle's business for two months. I answered emails,","",34.0],["","organised papers and sometimes spoke to customers on the phone.","",40.6],["","Good. Being organised is very important here because we have a lot of documents and customer","",45.2],["","information. That's fine. I like keeping things in the right place.","",50.9],["","Excellent. The job is three days a week. Monday, Wednesday and Friday. On Mondays and Fridays,","",56.6],["","you start at nine, but on Wednesday you start at ten o'clock because we have a staff meeting first.","",63.7],["","That works well for me. What would I usually do during the day?","",70.3],["","Mostly answer emails and prepare documents. You'll also take messages when customers phone.","",75.0],["","Sometimes we'll ask you to make copies of documents for meetings.","",81.4],["","Okay. Do I need to wear anything special?","",85.7],["","Nothing too formal. A shirt or smart top is fine,","",89.6],["","but please wear black shoes. Trainers aren't suitable in the office.","",93.6],["","No problem. How much do you pay?","",98.8],["","The starting rate is £12 an hour. After three months, it can increase if everything goes well.","",101.8],["","Great. How can I apply?","",108.4],["","Please bring your CV to the office. Ask for Mr Taylor at the front desk.","",111.0],["","He's interviewing applicants on Tuesday and Thursday this week.","",116.2],["","Thursday would be better for me.","",120.2],["","Perfect. Come any time between two and four.","",122.8],["","Thanks very much.","",126.8],["","You're welcome.","",128.8]]},
{"id":"wb-08","u":8,"book":"Workbook","title":"Travel and transport","dur":130,"audio":"audio/a2/workbook/unit-08.mp3","lines":[["","Good afternoon. Northside train station. How can I help?","",4.8],["","Hi. I'm travelling to Brighton tomorrow and I'd like some information about the trains.","",9.3],["","Certainly. Are you travelling in the morning or afternoon?","",15.6],["","In the morning. I need to be in Brighton before lunch time.","",20.1],["","No problem. Before I check the trains, could I take your name?","",24.6],["","Yes. It's Sarah Blake. Could you spell your surname for me?","",29.3],["","Of course. It's B-L-A-K-E. Thank you.","",34.8],["","Now, there's a train at 8.10 but that one stops at every station. The faster train leaves at 8.40.","",40.6],["","I'd prefer the faster one. Does it go directly to Brighton?","",48.6],["","Not quite. You need to change once at Greenford.","",53.4],["","Don't worry. You'll have about 20 minutes to get to the next train.","",57.4],["","That should be enough. How much is the ticket?","",61.4],["","A normal single ticket is £22. But if you have a student card, it's only £17.","",64.8],["","Great. I'm a student and I have my card with me.","",72.2],["","Perfect. Would you like to reserve a seat?","",76.1],["","Yes, please. I'd rather sit by the window if possible. I don't really like aisle seats.","",79.2],["","That's fine. There are still several window seats available.","",85.8],["","Great. Can I take my bicycle on the train?","",89.8],["","Yes, but there's only space for four bicycles,","",93.8],["","so you need to book a place for it before travelling.","",97.4],["","OK. Where should I go when I arrive at the station tomorrow?","",101.0],["","Your train normally leaves from Platform 5, but tomorrow it will leave from Platform 3","",105.8],["","because some work is being done near Platform 5.","",112.0],["","I'm glad I asked.","",115.7],["","Yes, it's always worth checking. Try to arrive about 15 minutes before departure.","",117.9],["","I will. Thanks for your help.","",124.2],["","You're welcome. Have a good journey.","",127.1]]},
{"id":"wb-09","u":9,"book":"Workbook","title":"Cities, Towns and Neighbourhoods","dur":139,"audio":"audio/a2/workbook/unit-09.mp3","lines":[["","Good morning, Hilltown Information Office. How can I help?","",5.5],["","Hi, my family and I are moving to Hilltown next month and I'd like to know more about the area.","",9.7],["","Of course, I can send you some information later. First, could I take your name?","",16.1],["","Yes, I'm David Palmer.","",22.2],["","Could you spell your surname, please?","",25.3],["","Sure, it's P-A-L-M-E-R.","",28.2],["","Thank you. Do you know which neighbourhood you're moving to?","",33.4],["","Yes, our new house is in Westwood. We chose it because my wife works nearby.","",37.7],["","That's a popular area for families. There's a primary school,","",43.8],["","several shops and a large playground.","",47.8],["","That sounds good. We have two young children. Is there a supermarket within walking distance?","",51.0],["","Yes, there are actually two. The larger one is on Station Road.","",57.5],["","It stays open until 10 o'clock every evening except Sunday.","",62.7],["","Excellent. What about public transport?","",67.3],["","Bus number 18 goes through Westwood.","",71.0],["","It stops outside the supermarket and then continues to the town centre.","",74.0],["","Is there a train station too?","",79.0],["","Yes, but it's on the other side of town.","",81.6],["","The easiest way to reach it is by bus. The journey from Westwood takes about 25 minutes.","",84.7],["","Okay, my children also enjoy being outdoors. Is there a park nearby?","",91.4],["","Yes, Oak Park is about a 15-minute walk away.","",97.6],["","It has a playground and a large lake. People often walk or cycle around it.","",101.4],["","Lovely. Is the neighbourhood generally quiet?","",107.4],["","During the week, yes. Station Road can get quite noisy on Saturday afternoons","",111.1],["","because many people come to do their shopping.","",117.1],["","That shouldn't be a problem. And is there a doctor near Westwood?","",120.0],["","Yes, the health centre is on Market Street next to the pharmacy.","",124.8],["","It's about 10 minutes away by bus.","",129.4],["","Great. That's all I needed. Thank you very much.","",132.0],["","You're welcome. I hope the move goes well.","",135.8]]},
{"id":"wb-10","u":10,"book":"Workbook","title":"Technology and everyday life","dur":134,"audio":"audio/a2/workbook/unit-10.mp3","lines":[["","Hello. Digital Skills Club. How can I help?","",4.2],["","Hi. I saw your poster at the library and I'd like to join one of your classes.","",9.2],["","Of course. I'll take some details first. What's your name?","",15.0],["","I'm Chloe Grant. Could you spell your surname, please?","",19.4],["","Yes, it's G-R-A-N-T.","",23.1],["","Thank you. We have several classes. What would you like help with?","",29.1],["","I can use my phone quite well, but I've just bought a new laptop and I'd like to learn how to use it better.","",34.1],["","Then, our everyday technology class might be right for you. Students learn how to organise files, use useful apps and keep their information safe online.","",41.1],["","That sounds useful. When is the class?","",52.1],["","We have one on Tuesday afternoon and another on Thursday evening.","",55.1],["","The evening class is more popular with people who work during the day.","",60.1],["","Thursday would be much better for me.","",64.1],["","Fine. It starts at 6.15.","",67.1],["","We ask students to arrive about 10 minutes early, so please be here by 6.05.","",70.1],["","No problem. Do I need to bring my own computer?","",76.1],["","You can, but you don't have to. We have computers here. However, please bring your phone because","",80.1],["","one part of the lesson is about connecting different devices.","",87.3],["","OK, how many people are usually in the class?","",91.2],["","The maximum is 12, but there are normally around 8. Small groups make it easier for the teacher","",95.6],["","to help everyone.","",101.7],["","Good, and how much does it cost?","",103.4],["","It's £8 for each class. You can pay online or at the centre when you arrive.","",107.3],["","Where exactly is the class held? We're inside the community centre on Park","",113.8],["","Road. Go through the main entrance and take the stairs to the first floor. The class is","",118.4],["","in Room 5. Great! Can I book a place now?","",123.9],["","Certainly. I'll add your name to Thursday's class.","",128.6],["","Thanks very much.","",132.8]]},
{"id":"wb-11","u":11,"book":"Workbook","title":"Health, exercise and sleep","dur":136,"audio":"audio/a2/workbook/unit-11.mp3","lines":[["","Good afternoon. Wellbeing centre. How can I help?","",5.8],["","Hi. I'd like some information about your healthy living programme.","",9.8],["","My friend joined last month and recommended it to me.","",14.3],["","Certainly. I'll take a few details first. What's your name?","",18.5],["","I'm Emma Norton. Could you spell your surname, please?","",23.1],["","Sure. It's N-O-R-T-O-N.","",27.8],["","Thank you. What would you most like to improve?","",33.8],["","Probably my sleep. I usually go to bed at about 11, but I sometimes lie awake for a long time.","",37.4],["","In the morning, I often feel sleepy, especially when I have to get up early for work.","",45.1],["","I see. Do you drink much coffee?","",51.3],["","I used to drink three cups a day, including one after dinner.","",54.6],["","Now I only have coffee in the morning, and I drink water with my evening meal.","",59.2],["","That's a good change. What about exercise?","",64.6],["","I go swimming once a week. I'd like to exercise more often, but I don't enjoy going to the gym.","",68.2],["","You could try our evening walking group. It meets twice a week.","",75.6],["","Tuesday's walk starts at seven, and the Thursday walk starts half an hour earlier.","",79.8],["","Thursday sounds good. How long do you walk for?","",85.1],["","About an hour. We normally meet outside the centre and walk through the park.","",88.9],["","Do I need to bring anything?","",94.3],["","Comfortable shoes are important. We also recommend bringing a bottle of water,","",96.4],["","especially when the weather is warm.","",101.5],["","Okay. And what time should I try to go to sleep?","",104.2],["","That depends on when you get up. You said you start work early. What time does your alarm ring?","",108.5],["","At 6.30.","",114.9],["","Then try to be asleep by around 10.30. Also, avoid looking at a screen for 30 minutes before","",116.8],["","bed. Reading a book can be a better way to relax.","",123.8],["","I can try that. I enjoy reading anyway.","",127.8],["","Excellent. Small changes can make a big difference.","",131.6]]},
{"id":"wb-12","u":12,"book":"Workbook","title":"Sports and competitions","dur":131,"audio":"audio/a2/workbook/unit-12.mp3","lines":[["","Hello, Riverside Sports Centre. How can I help?","",5.0],["","Hi. I'm calling about the running event next month. I'd like to enter.","",9.0],["","Certainly. I can complete the registration with you now. Can I have your name?","",14.8],["","Yes. I'm Hannah Cole.","",20.4],["","Could you spell your surname, please?","",23.0],["","Sure. It's C-O-L-E.","",26.0],["","Thank you. We have two races this year. A 5km race and a 10km race. Which would you like to enter?","",30.0],["","I thought about doing 10km, but I've only been running regularly for six months.","",39.1],["","I think the 5km race is better for me this time.","",45.0],["","Good choice. You can always try the longer one next year. The event is on Sunday 12th.","",49.0],["","The race itself begins at 11, but registration closes at 10.15.","",55.0],["","OK. I'll make sure I'm there before then.","",60.6],["","Good. Have you taken part in a running competition before?","",64.1],["","No. This will be my first one. I usually run in the park near my house three times a week.","",68.3],["","Great. The route is mostly through Riverside Park. There's one short hill near the middle,","",75.1],["","but the rest of the route is quite flat.","",81.0],["","That sounds fine. Do runners need to bring their own water?","",84.0],["","You can if you want, but we provide water at two points along the route.","",88.4],["","You should definitely bring a small towel for after the race.","",93.1],["","OK. How much does it cost to enter?","",97.0],["","It's normally £14, but students pay £10 if they show a student card.","",100.2],["","Perfect. I'm a student.","",106.5],["","Excellent. After the race, everyone gets a drink and some fruit.","",109.0],["","The first three runners also receive a prize.","",113.4],["","Where do I collect my race number?","",117.0],["","From the information desk inside the sports centre. It will be open from 9 o'clock.","",119.5],["","Great. Thanks for your help.","",125.1],["","You're welcome. Good luck with your training.","",127.7]]},
{"id":"wb-13","u":13,"book":"Workbook","title":"Weather and seasonal activities","dur":129,"audio":"audio/a2/workbook/unit-13.mp3","lines":[["","Hello, Mountain View Visitor Centre. How can I help you?","",5.8],["","Hi, I'm planning to visit Mountain View with some friends during the winter holiday.","",10.3],["","I'd like to know what activities are available.","",15.3],["","Certainly. Can I take your name first?","",18.4],["","Yes, I'm Peter Shaw.","",21.8],["","Could you spell your surname, please?","",24.7],["","Of course. It's S-H-A-W.","",27.4],["","Thank you. When are you planning to come?","",32.2],["","Next Friday. We were thinking about Saturday, but one of my friends has to work that day.","",35.6],["","Friday should be a good day. We had heavy snow earlier this week,","",41.9],["","so there are lots of winter activities available.","",46.1],["","Great. We'd really like to try skiing.","",49.4],["","The beginner ski lesson would be suitable. The morning lesson starts at nine,","",52.7],["","but that group is already full. There are still places in the afternoon lesson at 1.30.","",57.6],["","That's fine. None of us has skied before, so a lesson would be useful.","",63.6],["","Definitely. You can rent all the equipment here. We provide skis and boots,","",69.0],["","but everyone needs to bring their own gloves.","",74.4],["","Okay. What will the weather be like?","",77.6],["","It should stay dry, but it will be very cold.","",80.8],["","The temperature may fall to minus six degrees in the morning.","",84.6],["","We'll make sure we wear warm clothes. How much is the lesson?","",88.7],["","The lesson normally costs £25 per person.","",93.0],["","Because you're coming on a weekday, the price is only £20.","",97.0],["","Good. Is there anything to do after the lesson?","",101.4],["","Yes. You can go ice skating until seven o'clock or visit the cafe.","",105.0],["","They serve hot drinks, soup and sandwiches.","",110.3],["","The cafe sounds good after being outside all afternoon.","",113.9],["","I'm sure it will. Just remember that it gets dark early in winter,","",117.9],["","so don't start any long walks late in the day.","",122.6],["","Good advice. Thanks very much.","",126.2]]},
{"id":"wb-14","u":14,"book":"Workbook","title":"Animals and Wildlife","dur":134,"audio":"audio/a2/workbook/unit-14.mp3","lines":[["","Hello. Riverbank Animal Centre. How can I help?","",4.2],["","Hi. I saw some information online about helping at the centre and I'm interested in becoming a","",9.4],["","volunteer. That's great. We're always looking for people to help. Can I take your name first?","",15.9],["","Yes, I'm Sophie Lane. Could you spell your surname, please?","",23.6],["","Of course. It's L-A-N-E.","",28.3],["","Thank you. Have you worked with animals before?","",33.3],["","Not as a job, but my family has always had pets.","",37.3],["","We have two cats now and I used to look after my neighbour's dog when she was away.","",41.3],["","That's useful. Most new volunteers start by helping with the rabbits.","",46.3],["","They need fresh food, clean water and a clean living area every day.","",52.3],["","I'd be happy to do that. When do you need volunteers?","",57.3],["","We need the most help at weekends. Saturday morning is already quite busy, but we still need people on Sunday.","",61.3],["","Sunday is actually better for me. What time would I start?","",69.3],["","Volunteers usually arrive at 8.30. The centre opens to visitors at 10, so we try to finish most of the cleaning before then.","",74.3],["","OK. What should I wear?","",83.3],["","comfortable clothes are best. Please wear strong boots because some areas can","",86.3],["","get wet and muddy. Fine. Do volunteers work with the wild animals too? Not at","",91.2],["","first. We sometimes care for injured birds and other local wildlife but only","",98.4],["","experienced volunteers work closely with them. I understand. Is there any training?","",104.2],["","Yes, all new volunteers attend a short training session. The next one is on the 16th and lasts","",110.5],["","about two hours.","",118.3],["","Great! Is there anything I should bring to that?","",119.8],["","Just a notebook. We'll provide everything else.","",123.9],["","Perfect! I'd definitely like to join.","",127.0],["","Excellent! I'll add your name to the list.","",130.4]]},
{"id":"wb-15","u":15,"book":"Workbook","title":"Nature and the Environment","dur":131,"audio":"audio/a2/workbook/unit-15.mp3","lines":[["","Good afternoon. Green Community Centre, how can I help you?","",5.8],["","Hi, I saw a notice about your tree planting day and I'd like to take part.","",10.2],["","Wonderful. We still need a few more volunteers. Can I take your name?","",16.5],["","Yes, it's Laura Finch.","",21.8],["","Could you spell your surname please?","",24.6],["","Of course, it's F-I-N-C-H.","",27.4],["","Thank you. This time we're planting trees near the river. We planted some in the town park last year","",32.7],["","so we wanted to choose a different area.","",39.4],["","That sounds good. I cycle along the river sometimes and it would be nice to see more trees there.","",42.2],["","Exactly. The planting day is next Sunday. We normally organise these events on Saturdays","",49.0],["","but there's a big market in the area that day.","",55.0],["","Sunday works for me. When does it begin?","",58.5],["","We start at ten o'clock but please arrive by nine thirty. We need to put everyone into","",61.6],["","small groups and explain how to plant the trees correctly.","",67.1],["","Sure. Do I need any experience?","",71.4],["","Not at all. A team leader will show you what to do.","",74.8],["","We provide all the tools including gloves and small spades.","",78.2],["","Great. What should I wear?","",82.7],["","Old clothes are best. Please bring a jacket too. The forecast says it should stay dry","",85.6],["","but it may be cool near the water.","",91.8],["","Okay. How many trees are you hoping to plant?","",94.6],["","We originally planned to plant fifty but a local business gave us some extra trees.","",98.3],["","We now hope to plant seventy.","",103.8],["","Wow. That's quite a lot.","",106.6],["","It is but we already have nearly forty volunteers. We'll also stop for a short break at midday.","",109.5],["","Will there be food?","",117.1],["","We provide fruit and water. Please bring your own lunch though because the event","",118.8],["","continues until about three.","",123.1],["","No problem. I'll be there.","",125.8],["","Excellent. Thanks for helping us.","",128.1]]},
{"id":"wb-16","u":16,"book":"Workbook","title":"Films, Music, Books and Entertainment","dur":138,"audio":"audio/a2/workbook/unit-16.mp3","lines":[["","Hello, Riverside Library. How can I help?","",7.0],["","Hi. I saw an advertisement for your evening entertainment club and I'd like some information.","",11.0],["","Certainly. We organise different activities each week. Can I take your name first?","",18.0],["","Yes, I'm Nathan Bell.","",24.0],["","Could you spell your surname, please?","",27.0],["","Sure, it's B-E-L-L.","",30.0],["","Thank you. What kind of entertainment are you most interested in?","",34.0],["","I love films and music, but I'm especially interested in books. I read almost every evening.","",39.0],["","Then you might enjoy our reading group. We meet twice a month and discuss a different book each time.","",46.0],["","That sounds good. Which day do you meet?","",53.0],["","We used to meet on Tuesdays, but this month the meetings are on Wednesday evenings because the library has another event on Tuesdays.","",56.0],["","Wednesday is fine. What time does it start?","",64.0],["","At 7.15. Most people arrive a little earlier and have tea or coffee before the discussion begins.","",68.0],["","Nice. What book are you reading at the moment?","",75.0],["","It's an adventure story called The Long Road. It's about two friends travelling through the mountains.","",79.0],["","The writer is coming to our next meeting.","",85.0],["","Really? That sounds interesting.","",88.0],["","Yes. After the discussion, she'll answer questions and talk about how she became a writer.","",91.0],["","Great. Do I have to buy the book?","",98.0],["","No. Members can borrow a copy from the library for three weeks. Just show your library card at the front desk.","",101.0],["","Perfect. Is there a cost to join the group?","",109.0],["","The reading group itself is free. We sometimes organise cinema trips and members pay for those separately.","",112.0],["","Do you have any other events this month?","",120.0],["","Yes, there's a live music evening on the 24th. A local singer will perform in the café. Tickets are £6.","",122.0],["","I might come to that too.","",132.0],["","Great! I'll give you the details when you come to the reading group.","",134.0]]},
{"id":"wb-17","u":17,"book":"Workbook","title":"Interesting people and their lives","dur":118,"audio":"audio/a2/workbook/unit-17.mp3","lines":[["","Welcome to young people doing interesting things. Today we're talking to someone who started his own","",6.0],["","small business while he was still at school. Thanks for coming. Could you introduce yourself?","",12.7],["","Sure, I'm Daniel Moore.","",19.2],["","Could you spell your surname for our listeners?","",22.0],["","Yes, it's M-O-O-R-E.","",25.1],["","Thanks, Daniel. Where are you from?","",30.0],["","I was born in Manchester, but when I was six, my family moved to Bristol.","",32.9],["","I've lived there ever since.","",37.8],["","Tell us about your business. How did it begin?","",39.8],["","I've always enjoyed making things. When I was 16, I started making simple wooden boxes at home.","",43.3],["","At first, they were just presents for family members.","",50.2],["","So when did it become a business?","",53.8],["","A friend asked if she could buy one. Then other people became interested.","",56.6],["","I started selling the boxes online, and after a few months, I was getting several orders each week.","",61.0],["","Did you make everything at home?","",67.4],["","At first, yes. I worked in our garage because there wasn't enough space in my bedroom.","",70.0],["","Last year, I rented a small workshop near my house.","",75.8],["","Do you work there alone?","",79.6],["","Not anymore. My cousin works with me three days a week.","",81.8],["","She answers customer messages and takes photos of our products for the website.","",85.8],["","What do you enjoy most about your work?","",90.8],["","I like designing new things. Making the same box again and again can get boring,","",93.8],["","so creating something different is much more exciting.","",99.4],["","And what are your plans for the future?","",103.1],["","I'd like to open a small shop one day. I enjoy selling online,","",106.1],["","but I think it would be nice to meet more of my customers.","",110.3],["","Sounds like a great plan. Thanks for talking to us.","",113.7]]},
{"id":"wb-18","u":18,"book":"Workbook","title":"Festivals, Celebrations and Traditions","dur":132,"audio":"audio/a2/workbook/unit-18.mp3","lines":[["","Hello, Oakfield Community Centre, how can I help?","",5.3],["","Hi, I saw a poster about your spring celebration and I'd like to bring my family.","",11.2],["","Wonderful, it's a traditional event we organise every year. Can I take your name first?","",17.8],["","Yes, I'm Robert Dean.","",24.7],["","Could you spell your surname, please?","",27.6],["","Of course, it's D-E-A-N.","",30.6],["","Thank you. This year's celebration will be on Saturday the 9th.","",35.2],["","Last year we held it on a Sunday, but Saturday is easier for most families.","",40.0],["","Great. What time should we arrive?","",45.6],["","The doors open at 10, but the first activity begins at 10.45.","",48.6],["","It's a traditional dance performed by children from the local school.","",53.8],["","My daughter will enjoy that. What else is happening?","",58.3],["","After the dance, there'll be music and several family games.","",62.3],["","At lunchtime, local families will serve traditional food.","",66.5],["","What kind of food?","",70.9],["","There'll be rice dishes, meat and vegetables.","",72.7],["","We'll also have a special sweet cake that people usually make for this celebration.","",76.3],["","Sounds delicious. Can children take part in the activities?","",82.2],["","Absolutely. One popular activity is making traditional decorations from paper.","",87.0],["","Children can take them home afterwards.","",93.0],["","Nice. Is there anything we should bring?","",96.1],["","If the weather is good, some activities will be outside, so bring a hat for the children.","",99.4],["","It can get quite sunny in the afternoon.","",105.4],["","OK. Do we need to buy tickets?","",108.6],["","Entry is free for children under 12. Adult tickets are £7 and that includes all the activities.","",111.5],["","Excellent. Can we buy tickets when we arrive?","",119.6],["","Yes, but the event is usually busy, so coming early is a good idea.","",123.3],["","We will. Thanks for your help.","",129.1]]},
{"id":"wb-19","u":19,"book":"Workbook","title":"Childhood and Memories","dur":129,"audio":"audio/a2/workbook/unit-19.mp3","lines":[["","Welcome back to Growing Up. Today, we're asking people about things they remember from childhood.","",5.4],["","Could you introduce yourself? Of course. I'm Michael Green.","",12.4],["","Could you spell your surname, please? Sure. It's G-R-E-E-N.","",17.8],["","Thanks, Michael. Where did you live when you were a child?","",25.9],["","I was born in a city, but when I was five, we moved to a small village in the countryside.","",30.2],["","My parents wanted somewhere quieter for us to grow up.","",36.0],["","What did you like about living there? I loved being outdoors. There was a field","",39.8],["","behind our house, and my friends and I spent hours there. We played football,","",45.3],["","climbed trees, and sometimes had picnics. What was school like?","",50.1],["","It was quite small. I started there when I was six, and there were only about 20 children in my class.","",55.3],["","I was nervous at first, but I soon made friends. Did you have a favourite teacher?","",62.2],["","Yes, Mr Thomas. He taught science. His lessons were always interesting,","",68.6],["","because we did simple experiments instead of only reading from books.","",73.6],["","What did you usually do when you got home from school?","",78.2],["","My mum usually gave me something to eat first. Then I did my homework. After that,","",81.9],["","I often rode my bike to my best friend's house. Do you remember your birthdays?","",87.4],["","Definitely. My parents usually organised a small party at home. On my tenth birthday,","",93.4],["","I got a camera. I took pictures of absolutely everything for months.","",99.1],["","What is your favourite childhood memory? Probably our summer holidays. We went to","",104.9],["","the same place every year and stayed in a small house near a forest.","",110.6],["","My brother and I loved exploring it with our dad.","",115.0],["","Do you still have any of those old photographs?","",118.6],["","Yes, I keep them in a box at my parents' house. Looking at them always brings back good memories.","",122.0]]},
{"id":"wb-20","u":20,"book":"Workbook","title":"Everyday problems and solutions","dur":125,"audio":"audio/a2/workbook/unit-20.mp3","lines":[["","Good afternoon. City Bus lost property office. How can I help?","",5.5],["","Hi, I think I left my bag on a bus this morning.","",10.6],["","Okay, I'll take some details and see if anyone has found it. Can I have your name first?","",14.6],["","Yes, I'm James Cook.","",21.7],["","Could you spell your surname, please?","",24.5],["","Of course. It's C-O-O-K.","",26.5],["","Thank you. Do you remember which bus you were on?","",31.5],["","Yes, it was the number 27. I usually take the 19, but that bus was late this morning, so I took a different one.","",35.5],["","I see. What time did you get off the bus?","",44.5],["","At about 8.20. I didn't notice the bag was missing until I arrived at work about 15 minutes later.","",48.5],["","Can you describe the bag?","",55.5],["","It's a small black backpack.","",57.5],["","I also have a blue one at home, but the one I lost is definitely black.","",60.5],["","And what was inside it?","",65.5],["","My lunch, a notebook and a pair of glasses.","",67.5],["","Luckily I had my phone and wallet in my coat pocket.","",71.5],["","That's good. Did the bag have your name on it?","",74.5],["","No, but there's a small green keyring on the front.","",78.5],["","It looks like a football.","",82.5],["","All right. We haven't received a black backpack yet, but drivers usually bring lost items here after their shift.","",84.5],["","The bus you took should return to the station at 2.30 this afternoon.","",92.5],["","So, should I call again later?","",97.5],["","Yes. Try us after 3. If we find the bag, you can collect it from the lost property office next to the ticket desk.","",100.5],["","OK. What time do you close?","",108.5],["","At six today. If you can't come before then, we can keep the bag here for you.","",111.5],["","Great. Thanks. I was worried I'd lost it completely.","",117.5],["","Hopefully it will turn up this afternoon.","",121.5]]},
{"id":"wb-21","u":21,"book":"Workbook","title":"Helping people and community life","dur":140,"audio":"audio/a2/workbook/unit-21.mp3","lines":[["","Hello, Eastside Community Kitchen. How can I help?","",6.1],["","Hi, my friend volunteers with you and she said you need more people to help.","",10.2],["","We do. Thanks for calling. Can I take your name first?","",16.2],["","Yes, I'm Matthew Ford.","",21.4],["","Could you spell your surname, please?","",24.2],["","Sure, it's F-O-R-D.","",27.1],["","Thank you. Have you done any volunteer work before?","",31.5],["","Yes. Last year I helped at a school event.","",35.8],["","I served drinks and helped clean up afterwards, but I've never worked in a community kitchen.","",39.5],["","That's absolutely fine. We prepare free meals for people who need them.","",45.7],["","New volunteers usually start by preparing vegetables.","",51.0],["","They wash them, cut them, and get them ready for cooking.","",54.7],["","Great. I cook quite a lot at home, so I'd be comfortable doing that.","",58.5],["","Excellent. We prepare meals on Wednesdays and Fridays.","",63.5],["","Wednesday is already quite busy, so we especially need help on the other day.","",68.0],["","Friday works well for me.","",73.4],["","Good. We start cooking at five, but volunteers need to arrive by four-forty-five","",75.5],["","so they can wash their hands, put their things away, and get ready.","",81.6],["","No problem. How long would I stay?","",85.6],["","Usually until about eight. We start serving the meals at six-thirty.","",89.0],["","Do I need to bring any equipment?","",94.5],["","No. We provide everything in the kitchen. Just wear comfortable clothes and closed shoes.","",97.0],["","Open shoes aren't safe when you're working around hot food.","",103.5],["","Okay. Is there anything else I can help with?","",107.5],["","Sometimes we need people to deliver meals to older residents.","",111.1],["","Volunteers usually go in pairs and travel by car.","",115.5],["","I have a car, so I could do that sometimes.","",119.5],["","That would be very helpful.","",123.0],["","Before you begin, there's a short training session.","",125.0],["","It lasts thirty minutes and explains the kitchen's safety rules.","",128.4],["","Great. When's the next one?","",133.2],["","This Thursday at six.","",135.8],["","Perfect. I'll be there.","",138.2]]},
{"id":"wb-22","u":22,"book":"Workbook","title":"Trying something new","dur":138,"audio":"audio/a2/workbook/unit-22.mp3","lines":[["","Hello, Creative Skills Centre. How can I help?","",5.1],["","Hi, I'm looking for a new hobby and a friend told me about your beginner courses.","",9.0],["","Great! We have several courses for people who want to try something different.","",14.7],["","Can I take your name first?","",19.7],["","Yes, I'm Thomas Riley.","",22.2],["","Could you spell your surname, please?","",25.0],["","Of course. It's R-I-L-E-Y.","",27.7],["","Thank you. What sort of things are you interested in?","",33.0],["","I work on a computer all day, so I'd like to do something with my hands.","",37.0],["","I've thought about painting, but I'm not very good at drawing.","",42.2],["","You don't need to be. We also have cooking, photography and pottery courses.","",46.5],["","I already cook quite a lot at home, and I use my phone for photos.","",52.6],["","Pottery sounds more unusual. I've never tried anything like that.","",57.2],["","Then our beginner course would be perfect. It's a four-week course,","",61.8],["","and you'll learn how to make simple bowls and cups.","",66.2],["","Nice! When are the classes?","",69.8],["","There's a Monday class and a Thursday class.","",72.5],["","Monday starts at 6, but Thursday is a little later.","",75.8],["","Thursday would be better, because I usually work late on Mondays.","",80.1],["","Fine. The Thursday class starts at 6.45 and lasts an hour and a half.","",84.6],["","Do I need to buy any equipment?","",91.2],["","No. We provide all the tools and materials.","",93.7],["","You should bring an old shirt, though, because your clothes may get dirty.","",97.3],["","Good idea. How many people are in each class?","",101.8],["","We allow a maximum of ten, but there are usually about eight.","",105.8],["","That gives the teacher enough time to help everyone.","",110.4],["","And how much is the course?","",114.0],["","It normally costs £50, but beginners joining this month pay £40 for all four classes.","",116.2],["","Great! Where is the pottery room?","",124.2],["","It's upstairs in room seven, opposite the photography room.","",127.0],["","Perfect. I'd like to give it a try.","",131.8],["","Excellent. I'll reserve a place for you.","",134.7]]},
{"id":"wb-23","u":23,"book":"Workbook","title":"Interesting places and different cultures","dur":134,"audio":"audio/a2/workbook/unit-23.mp3","lines":[["","Hello. City Exchange Club. How can I help?","",5.9],["","Hi. I saw some information about your cultural evening next week and I'd like to come.","",9.8],["","Great. I can give you all the details. Can I take your name first?","",16.0],["","Yes. I'm Ben Carter. Could you spell your surname, please?","",21.4],["","Of course. It's C-A-R-T-E-R.","",26.2],["","Thank you. This month our cultural evening is about Mexico.","",32.2],["","Last month we looked at Spain, so we wanted to choose somewhere different this time.","",37.2],["","Nice. I don't know much about Mexico, so it should be interesting.","",42.2],["","The evening begins with a short talk by a student who lived there for a year.","",47.2],["","She'll show photographs of different cities and talk about family life, school and food.","",52.2],["","What time does the talk start?","",59.2],["","The doors open at 6, but the talk begins at 6.30. Try to arrive a little earlier because it can get busy.","",61.2],["","I will. Is there any food to try?","",69.2],["","Yes. After the talk, visitors can try several dishes.","",72.2],["","dishes. One of them is a traditional soup made with vegetables and chicken.","",77.2],["","Great! I enjoy trying new food.","",82.9],["","Later there'll be a short dance lesson. You don't need any experience and everyone is","",86.4],["","welcome to join.","",91.9],["","That sounds fun. What should we wear?","",94.0],["","Anything comfortable. If you want to join the dancing, comfortable shoes are especially","",97.3],["","important.","",102.3],["","to know. Will there be anything to buy? Yes, there'll be a small market with handmade","",103.9],["","gifts, books and traditional clothes. Some of the students brought the items back from","",110.5],["","their travels. How much is the event? It's £6 for adults. Children under 12 can come","",115.8],["","for free. Perfect. Where is it being held? In the community hall besides Central Library.","",123.4],["","Great, thanks for the information.","",131.4]]},
{"id":"wb-24","u":24,"book":"Workbook","title":"Life in the past and life today","dur":128,"audio":"audio/a2/workbook/unit-24.mp3","lines":[["","Welcome back to Life Changes. Today we're talking to people about how their daily lives are different","",6.0],["","from when they were young. Could you introduce yourself? Certainly. My name's Robert James.","",12.7],["","Could you spell your surname please? Of course. It's J-A-M-E-S.","",19.9],["","Thanks Robert. Where did you live as a child?","",27.7],["","I grew up on a farm about 10 kilometres from the nearest town.","",31.3],["","It was a quiet place and there weren't many other children living nearby.","",35.6],["","How did you get to school? A school bus picked us up every morning. I had to leave home at 7.15","",40.9],["","because the bus stopped at several villages before reaching the school.","",48.1],["","What was school like then? We didn't have computers of course.","",52.6],["","We wrote everything by hand in our notebooks. If we needed information for homework we usually looked","",57.3],["","in books. What did you do after school? I often helped my parents on the farm. After that I played","",63.4],["","outside with my brother. We had a television but I was only allowed to watch it for about an hour","",71.5],["","each evening. How did your family do its shopping? We drove into town every Saturday. My mother made","",77.4],["","a long list because we needed enough food for the whole week. And how is your life different today?","",84.9],["","Well I live in a city now so everything is much closer. I can walk to several shops and I","",91.7],["","sometimes order food online. Communication is much easier too. Do you use technology a lot?","",98.2],["","Yes. I use my phone every day for messages, maps, news and even paying for things. When I was young","",106.0],["","I never imagined one small thing could do all of that. Is there anything you miss about the past?","",113.8],["","I miss how peaceful life on the farm was but I think modern life is more convenient.","",121.4]]}];
